//! The yewi design tokens as Rust constants, for UIs that do not draw with CSS.
//!
//! Each `--yi-<name>` custom property in `yewi/scss/tokens.scss` is the
//! constant `<NAME>` here: `--yi-space-sm` is [`SPACE_SM`]. The constants are
//! generated by `cargo xtask tokens`, so the stylesheet stays the one place a
//! token is defined.
//!
//! - **Colours** are a [`Color`]: the light and dark values, as sRGB. They
//!   are worked out for the default accent and neutral tint.
//! - **Lengths** are `f32` logical pixels, with `1rem` as 16.
//! - **Durations** are `f32` milliseconds, and an easing curve is the four
//!   numbers of its `cubic-bezier()`.
//! - **Fonts** are family names in order of preference.
//!
//! [`compact`] holds the tokens that the compact density changes.
#![no_std]

/// Which of a colour's two values to use.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Scheme {
    #[default]
    Light,
    Dark,
}

/// An sRGB colour with straight (not premultiplied) alpha.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Rgba {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Rgba {
    pub const fn new(r: u8, g: u8, b: u8, a: u8) -> Self {
        Self { r, g, b, a }
    }

    /// `[r, g, b, a]`, each from 0 to 1, still sRGB-encoded.
    pub const fn to_f32(self) -> [f32; 4] {
        [self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0, self.a as f32 / 255.0]
    }
}

/// A colour token: one value for each scheme.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Color {
    pub light: Rgba,
    pub dark: Rgba,
}

impl Color {
    pub const fn resolve(self, scheme: Scheme) -> Rgba {
        match scheme {
            Scheme::Light => self.light,
            Scheme::Dark => self.dark,
        }
    }
}

/// One layer of a shadow token. Lengths are logical pixels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Shadow {
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub color: Color,
}

